74: 	if r == nil {
75: 		panic(errors.New("expected non nil io.Reader"))
76: 	}
77: 	result := make(chan bool, 1)
78: 	select {
79: 	case b.operateState <- func(s *bState) { result <- len(s.ewmaDecorators) != 0 }:
80: 		return newProxyReader(r, b, <-result)
81: 	case <-b.ctx.Done():
82: 		return nil
83: 	}
