442: func (s *bState) draw(stat decor.Statistics) (io.Reader, error) {
443: 	decorFiller := func(buf *bytes.Buffer, group []decor.Decorator) (err error) {
444: 		for i, d := range group {
445: 			// need to call Decor in any case because of width synchronization
446: 			str, width := d.Decor(stat)
447: 			if i != 0 && err != nil {
448: 				continue
449: 			}
450: 			if w := stat.AvailableWidth - width; w >= 0 {
451: 				_, err = buf.WriteString(str)
452: 				stat.AvailableWidth = w
453: 			} else if stat.AvailableWidth > 0 {
454: 				trunc := runewidth.Truncate(stripansi.Strip(str), stat.AvailableWidth, "…")
455: 				_, err = buf.WriteString(trunc)
456: 				stat.AvailableWidth = 0
457: 			}
458: 		}
459: 		return err
460: 	}
461: 
462: 	for i, buf := range s.buffers[1:] {
463: 		err := decorFiller(buf, s.decorGroups[i])
464: 		if err != nil {
465: 			return nil, err
466: 		}
467: 	}
468: 
469: 	if s.trimSpace || stat.AvailableWidth < 2 {
470: 		err := s.filler.Fill(s.buffers[0], stat)
471: 		return io.MultiReader(
472: 			s.buffers[1],
473: 			s.buffers[0],
474: 			s.buffers[2],
475: 			strings.NewReader("\n"),
476: 		), err
477: 	}
478: 
479: 	stat.AvailableWidth -= 2
480: 	err := s.filler.Fill(s.buffers[0], stat)
481: 	return io.MultiReader(
482: 		s.buffers[1],
483: 		strings.NewReader(" "),
484: 		s.buffers[0],
485: 		strings.NewReader(" "),
486: 		s.buffers[2],
487: 		strings.NewReader("\n"),
488: 	), err
489: }
